import { CURSOR_MARKER, KIND } from "./types.js";
import { parseRefUrl } from "./parser.js";
function isObject(val) {
    return val !== null && typeof val === "object" && !Array.isArray(val);
}
export function isSegment(val) {
    return isObject(val) && KIND in val;
}
export function isCursorMarker(val) {
    return isObject(val) && CURSOR_MARKER in val;
}
export function isPattern(val) {
    return isObject(val) && !isSegment(val) && !isCursorMarker(val);
}
export function isValidRefUrl(str) {
    if (typeof str !== "string" || !str || !str.startsWith("automerge:")) {
        return false;
    }
    try {
        parseRefUrl(str);
        return true;
    }
    catch {
        return false;
    }
}
